public void distributeFileTask(Date startHandleDate, Date endHandleDate, String states, boolean processing) {
        List<String> handleStatus = new ArrayList<>();
        handleStatus.add(FileHandleStatus.INIT.getCode());
        handleStatus.add(FileHandleStatus.FAIL.getCode());
        if (StringUtils.isNotBlank(states)) {
            handleStatus.addAll(Arrays.stream(states.split(Constant.SEPARATOR)).map(String::valueOf).collect(Collectors.toList()));
        }
        if (processing) {
            handleStatus.add(FileHandleStatus.PROCESSING.getCode());
        }
        Calendar calendar = Calendar.getInstance();
        int startTime = calendar.get(Calendar.HOUR_OF_DAY);
        List<FileHandleTaskDo> reconFileHandleTaskDos = fileHandleTaskTunnel.selectFileTasks(handleStatus, startHandleDate, endHandleDate,  startTime);

        handleWithThreadPool(reconFileHandleTaskDos);
    }

public void handleWithThreadPool(List<FileHandleTaskDo> reconFileHandleTaskDos) {
        if (CollectionUtils.isEmpty(reconFileHandleTaskDos)) {
            return;
        }
        int length = reconFileHandleTaskDos.size();
        for (int i = 0; i < length; i++) {
            FileHandleTaskDo fileHandleTaskDo = reconFileHandleTaskDos.get(i);
            try {
                taskHandleThreadPoolExecutor.execute(() -> {
                    handle(fileHandleTaskDo);
                });
            } catch (RejectedExecutionException e) {
                log.info("文件处理任务被拒绝:{}", i);
                try {
                    Thread.sleep(Constant.THREAD_SLEEP_TIME);
                } catch (InterruptedException ex) {
                }
                i--;
            }
        }
    }

public void handle(FileHandleTaskDo fileHandleTaskDo) {
        log.info("文件处理任务：{}", fileHandleTaskDo);
        try {
            int num = this.fileHandleTaskTunnel.updateHandleTaskByKey(fileHandleTaskDo.getFileHandleTaskNo(),
                    fileHandleTaskDo.getHandleStatus(), FileHandleStatus.PROCESSING.getCode());
            if (num == 0) {
                return;
            }
            log.info("开始处理文件处理任务：{}", fileHandleTaskDo);

            if (Objects.equals(fileHandleTaskDo.getHandleStatus(), FileHandleStatus.SUCCESS.getCode())) {
                return;
            }
            // 源文件服务器
            String sourceServerNo = fileHandleTaskDo.getSourceServerNo();
            // 目标文件服务器
            String targetServerNo = fileHandleTaskDo.getTargetServerNo();
            FileServerDo sourceFileServerDo = fileServerTunnelI.selectByFileServerNo(sourceServerNo);
            FileServerDo targetFileServerDo = fileServerTunnelI.selectByFileServerNo(targetServerNo);

            IFileTaskHandleService fileTaskHandleService = fileTaskHandleServiceFactory.create(fileHandleTaskDo.getFileHandleType());

            if (fileTaskHandleService != null) {
                fileTaskHandleService.handle(fileHandleTaskDo, sourceFileServerDo, targetFileServerDo, baseFilePath);
                log.info("IFileTaskHandleService:{}",fileTaskHandleService.getClass().toString());
            }
            log.info("文件处理任务完成：{}", fileHandleTaskDo);
        } catch (Exception e) {
           log.error("执行文件处理任务失败:{}, error msg:",fileHandleTaskDo.getFileHandleTaskNo(), e);
//            dingErrorMsgComponent.sendError("执行文件处理任务失败:" + fileHandleTaskDo.getFileHandleTaskNo(), e);
        } finally {
        }
    }

