private void handle(SFTPUtils sf, String basePath) throws Exception {
        List<String> files = sf.getSftpFileAndDir(basePath, "");
        for(String file : files) {
            Date fDate = DateUtil.string2Date(file);
            if(fDate.before(DateUtil.plusDays(new Date(), days))) {
                log.info("删除文件夹：{}", basePath+ Constant.FILE_SEPARATOR +file);
                sf.deleteDir(basePath+ Constant.FILE_SEPARATOR +file);
            }
        }
    }

public void handle(List<String> fileNames, String resourceFilePath,
                                  String targetFilePath, String encoding,
                                  int fileTitleNumber,
                                  String titleServiceName, String bizDate) {
        StopWatch timeWatch = new StopWatch();
        log.info("开始处理文件，共{}个文件",fileNames.size());
        timeWatch.start();
        StopWatch stopWatch = new StopWatch();

        try {
            int count = 1;
            for (String fileName : fileNames) {
                String filePath = resourceFilePath + File.separator + fileName;
                log.info("开始处理文件{}", filePath);
                stopWatch.reset();
                stopWatch.start();
                // 创建文件解析器
                FileAssembleService fileAssembleFacade = fileAssembleServiceFactory.create(titleServiceName);
                Map<String, String> param = new HashMap<>();
                param.put("bizDate", bizDate);
                param.put("fileName", fileName);
                try (BaseParser parser = fileParserFactory.createParser(FileFormatTypeEnum.CSV, filePath, encoding)) {
                    parser.skip(fileTitleNumber);
                    writeFile(parser, targetFilePath, dynamicConfig.getFlushSize(), fileAssembleFacade, param, Constant.GBK);
                } catch (Exception e) {
                    log.error("文件处理失败", e);
                    throw e;
                } finally {
                    stopWatch.split();
                    log.info("处理第{}个文件{}完成,耗时{}", count, filePath, stopWatch.toSplitString());
                    count++;
                    stopWatch.stop();
                }
            }

            timeWatch.split();
            log.info("文件处理全部完成 耗时{}", timeWatch.toSplitString());
            timeWatch.stop();
        } catch (Exception e) {
            log.error("处理文件失败", e);
            throw new BusinessException("处理文件失败", e);
        }
    }
